const credentials = $input.first().json;
const body = $('Webhook').first().json.body || {};
if (!credentials.success) throw new Error('Credential lookup failed: ' + (credentials.error || 'unknown error'));
const accessToken = (credentials.access_token || '').trim();
if (!accessToken) throw new Error('No TikTok access token stored - reconnect this brand');
// TikTok access tokens live only 24 hours. T1-tiktok-token-refresh keeps them
// fresh; if it is not running this is where the failures show up.
const expiresAt = credentials.token_expires_at ? new Date(credentials.token_expires_at) : null;
if (expiresAt && expiresAt.getTime() < Date.now()) {
  throw new Error('TikTok access token expired at ' + credentials.token_expires_at + ' - is the T1 refresh workflow active?');
}
const caption = (body.caption || '').trim();
if (!caption) throw new Error('caption is required');
const mediaUrls = (Array.isArray(body.media_urls) ? body.media_urls : [])
  .filter(u => typeof u === 'string' && u.trim());
if (!mediaUrls.length) throw new Error('TikTok has no text-only post - media_urls is required');
const mediaType = body.media_type || (mediaUrls.length > 1 ? 'carousel' : 'image');
if (mediaType === 'video' && mediaUrls.length !== 1) throw new Error('A TikTok video requires exactly one URL');
if (mediaType === 'carousel' && (mediaUrls.length < 2 || mediaUrls.length > 35)) throw new Error('A TikTok photo carousel requires 2 to 35 images');
// TikTok truncates hard: 2200 for a video title, 90 for a photo post title.
const isPhoto = mediaType !== 'video';
const titleCap = isPhoto ? 90 : 2200;
const title = caption.slice(0, titleCap);
return [{ json: {
  access_token: accessToken,
  branch_id: body.branch_id,
  caption: caption,
  title: title,
  description: isPhoto ? caption.slice(0, 4000) : '',
  media_type: mediaType,
  media_urls: mediaUrls,
  is_photo: isPhoto,
  requested_privacy: body.privacy_level || null
} }];

const src = $('Extract & Normalize Request').first().json;
const res = $input.first().json || {};
if (res.error && res.error.code && res.error.code !== 'ok') {
  throw new Error('creator_info failed: ' + (res.error.message || res.error.code));
}
const info = res.data || {};
const options = Array.isArray(info.privacy_level_options) ? info.privacy_level_options : [];
if (!options.length) throw new Error('TikTok returned no privacy_level_options for this account');

// Never silently publish MORE publicly than asked, and never silently downgrade
// to private while reporting success -- either surprise is worse than a clear
// error. An unaudited app only ever gets SELF_ONLY here, which is exactly the
// signal the operator needs to see.
const requested = src.requested_privacy;
let privacy;
if (requested) {
  if (!options.includes(requested)) {
    throw new Error('privacy_level ' + requested + ' is not available for this account. TikTok offers: ' + options.join(', ') + '. An app that has not passed TikTok\'s Content Posting audit only ever gets SELF_ONLY.');
  }
  privacy = requested;
} else {
  privacy = options.includes('PUBLIC_TO_EVERYONE') ? 'PUBLIC_TO_EVERYONE' : options[0];
}

return [{ json: { ...src,
  privacy_level: privacy,
  privacy_options: options,
  creator_nickname: info.creator_nickname || null,
  creator_username: info.creator_username || null,
  disable_comment: !!info.comment_disabled,
  disable_duet: !!info.duet_disabled,
  disable_stitch: !!info.stitch_disabled,
  max_video_post_duration_sec: info.max_video_post_duration_sec || null
} }];

const src = $('Choose Privacy & Settings').first().json;
const res = $input.first().json || {};
if (res.error && res.error.code && res.error.code !== 'ok') {
  throw new Error('TikTok rejected the post: ' + (res.error.message || res.error.code));
}
const publishId = res.data && res.data.publish_id;
if (!publishId) throw new Error('TikTok returned no publish_id');
// Init succeeding means almost nothing -- format, duration and URL-fetch checks
// all happen asynchronously, so we must poll to a terminal state before
// reporting success to the caller.
return [{ json: { ...src, publish_id: publishId, attempt: 0 } }];

const src = $('Start Polling').first().json;
const prev = $input.first().json || {};
// The previous loop iteration's attempt count rides on the Wait node's item.
const attempt = Number($('Wait Before Status Check').first().json.attempt || 0) + 1;
const MAX_ATTEMPTS = 8;   // 8 x 15s = ~2 minutes

let parsed = prev.body;
if (typeof parsed === 'string') { try { parsed = JSON.parse(parsed); } catch (e) { parsed = null; } }
const data = (parsed && parsed.data) || {};
const errObj = (parsed && parsed.error) || {};
const status = data.status || null;

if (errObj.code && errObj.code !== 'ok') {
  return [{ json: { ...src, attempt, done: true, outcome: 'failed',
    error: 'Status check failed: ' + (errObj.message || errObj.code) } }];
}

if (status === 'PUBLISH_COMPLETE' || status === 'SEND_TO_USER_INBOX') {
  const ids = data.publicaly_available_post_id;   // TikTok's own spelling
  const postId = Array.isArray(ids) && ids.length ? String(ids[0]) : null;
  return [{ json: { ...src, attempt, done: true, outcome: 'published',
    status: status,
    // A post id comes back ONLY for public, moderation-approved posts, so an
    // unaudited (SELF_ONLY) post legitimately has none. Fall back to publish_id
    // so the row is still traceable.
    post_id: postId || src.publish_id, has_public_post_id: !!postId } }];
}

if (status === 'FAILED') {
  return [{ json: { ...src, attempt, done: true, outcome: 'failed',
    error: 'TikTok rejected the media: ' + (data.fail_reason || 'unknown reason') } }];
}

if (attempt >= MAX_ATTEMPTS) {
  return [{ json: { ...src, attempt, done: true, outcome: 'needs_review',
    error: 'Still ' + (status || 'processing') + ' after ' + (attempt * 15) + 's. CHECK THE ACCOUNT - this may still publish on its own. Not retried automatically because that risks a double post.' } }];
}

return [{ json: { ...src, attempt, done: false, status: status } }];

const src = $input.first().json || {};
// needs_review is a distinct outcome from failed: the post may yet go live, so
// S1 must NOT retry it. Its 'Interpret Publish Result' honours this flag.
return [{ json: { success: false, needs_review: true, code: 'processing_timeout',
  error: src.error || 'TikTok was still processing when we stopped polling' } }];

const item = $input.item.json || {};
const err = item.error || item;
let message =
  (err && err.error && err.error.message) ||
  (err && err.message) ||
  (typeof err === 'string' ? err : null) ||
  item.reason || null;
if (!message) { try { message = JSON.stringify(err).slice(0, 400); } catch (e) { message = 'Unknown publish error'; } }
const code = (err && err.error && (err.error.code || err.error.error_subcode)) || null;
return { json: { success: false, error: String(message).slice(0, 500), code: code } };
